mapper.select:
select *
from attractions

    area_code = #{sidoCode}

    AND si_gun_gu_code = #{gugunCode}


order by rand() limit 1;

select *,
ST_Distance_Sphere(
            POINT(longitude, latitude),             -- 저장된 컬럼 (순서 주의: 경도, 위도)
            POINT(#{search.lng}, #{search.lat})      -- 기준 위치 (순서 주의: 경도, 위도)
        ) AS distance_in_meters
FROM attractions

    ST_Distance_Sphere(
    POINT(longitude, latitude),
    POINT(#{search.lng}, #{search.lat})
    )

        <= #{search.m}



        AND content_type_id in

            #{contentType.id}



        AND (
        title LIKE CONCAT('%', #{search.query}, '%')
        OR
        overview LIKE CONCAT('%', #{search.query}, '%')
        )


ORDER BY distance_in_meters
LIMIT #{pageRequest.pageSize}
OFFSET #{pageRequest.offset};

select count(*)
FROM attractions

    ST_Distance_Sphere(
    POINT(longitude, latitude),
    POINT(#{lng}, #{lat})
    )

        <= #{m}



        AND content_type_id in

            #{contentType.id}



        AND (
        title LIKE CONCAT('%', #{query}, '%')
        OR
        overview LIKE CONCAT('%', #{query}, '%')
        )

;

select *
from attractions
where area_code = #{sidoCode}

    and si_gun_gu_code = #{gugunCode}

order by rand()
limit 1;
